
IF NOT EXISTS (SELECT * FROM sys.server_audits WHERE name = N'FormsAudit')
CREATE SERVER AUDIT [FormsAudit]
TO FILE 
(	FILEPATH = N'C:\audit\\'
	,MAXSIZE = 100 MB
	,MAX_FILES = 10
	,RESERVE_DISK_SPACE = ON
) WITH (QUEUE_DELAY = 1000, ON_FAILURE = CONTINUE, AUDIT_GUID = '00000000-0000-0000-0000-000000000000')
ALTER SERVER AUDIT [FormsAudit] WITH (STATE = ON)
